    'act.oncard': "Ekhadini",
    'item.cardonly.why': "Lawa mafayela asekhadini uqobo, hhayi ku-inthanethi. Vula leli khasi ekhadini noma ku-Wi-Fi yasendaweni ukuze uwabuke.",
    'home.oncard': "Izinto ezingu-{n} — zisekhadini, azikho kuwebhu",
