    "route.iphone-iphone.1.h": "दोनों में Wi-Fi और Bluetooth चालू करें",
    "route.iphone-iphone.1.p": "दोनों iPhone पर Control Centre खोलें और देखें कि Wi-Fi और Bluetooth चालू हैं। AirDrop दोनों का उपयोग करता है, भले किसी नेटवर्क की ज़रूरत न हो।",
