    "route.iphone-iphone.2.p": "फ़ाइल पाने वाले iPhone पर Settings → General → AirDrop खोलें। Everyone for 10 Minutes चुनें। Contacts Only चुना हो और भेजने वाला संपर्क सूची में न हो, तो दूसरा फ़ोन नहीं दिख सकता।",
