    "help.ios.1.p": "ਨੀਲੇ ਫ਼ੋਲਡਰ ਵਾਲੀ Files ਐਪ ਖੋਲ੍ਹੋ। ਡਾਊਨਲੋਡ ਕੀਤੇ ਦਸਤਾਵੇਜ਼ Files ਵਿੱਚ ਲੱਭੋ।",
