    "help.computer.2.h": "فائل کھولیں",
    "help.computer.2.p": "PDF کو PDF ریڈر میں، آڈیو کو آڈیو پلیئر میں اور ویڈیو کو ویڈیو پلیئر میں کھولیں۔ ضرورت ہو تو اس قسم کی فائل کے لیے مناسب ایپ انسٹال کریں۔",
    "help.computer.3.h": "پوری لائبریری رکھنے کے لیے",
