    "route.computer-iphone.1.p": "اهڙي تار استعمال ڪريو جيڪا ڊيٽا کڻي. ڪيتريون چارجنگ تارون ائين نٿيون ڪن ۽ هڪجهڙيون لڳن ٿيون — جيڪڏهن ڪمپيوٽر فون ڏيکاري ئي نٿو، ته سڀ کان پهريان ٻي تار آزمايو.",
    "route.computer-iphone.2.h": "فون تي Trust دٻايو",
    "route.computer-iphone.2.p": "iPhone تي “Trust this computer?” اچي ته Trust دٻايو ۽ فون جو پاس ڪوڊ لکو. ان سان فون ۽ ڪمپيوٽر وچ ۾ فائل موڪلڻ جي اجازت ملي ٿي.",
    "route.computer-iphone.3.h": "ڪمپيوٽر تي کوليو",
    "route.computer-iphone.3.p": "Mac تي Finder کوليو ۽ سائيڊبار ۾ iPhone چونڊيو. Windows تي Apple Devices کوليو، يا جيڪڏهن توهان جي سيٽ اپ ۾ iTunes استعمال ٿئي ٿو ته اهو کوليو.",
    "route.computer-iphone.4.h": "فائل ڪاپي ڪريو",
    "route.computer-iphone.4.p": "Files، يا iTunes ۾ File Sharing، واري حصي ۾ اهڙي ايپ چونڊيو جيڪا File Sharing جي سهولت ڏئي ٿي. فون تي موڪلڻ لاءِ فائل انهيءَ ايپ ۾ شامل ڪريو. ڪمپيوٽر تي موڪلڻ لاءِ فائل انهيءَ ايپ مان ڪمپيوٽر ۾ محفوظ ڪريو.",
    "route.computer-iphone.5.h": "وصول ٿيل فائل جانچيو",
    "route.computer-iphone.5.p": "iPhone تي فائل انهيءَ ايپ ۾ کوليو جيڪا File Sharing لاءِ استعمال ڪئي هئي. جيڪڏهن فائل ڪمپيوٽر تي موڪلي آهي ته اتي چونڊيل فولڊر ۾ کوليو. ڏسو ته فائل کلي ٿي.",
    "route.computer-android.name": "تار سان، فائل ٽرانسفر موڊ ۾",
    "route.computer-android.1.h": "فون ڳنڍيو",
    "route.computer-android.1.p": "ڊيٽا واري تار استعمال ڪريو، رڳو چارجنگ واري نه.",
    "route.computer-android.2.h": "فون کي فائل ٽرانسفر تي ڪريو",
    "route.computer-android.2.p": "Android پاڻمرادو رڳو چارجنگ لاءِ ڳنڍجي ٿو. \"Charging this device via USB\" واري اطلاع هيٺ ڇڪيو، دٻايو ۽ File Transfer چونڊيو. ان کان سواءِ ڪمپيوٽر کي ڪجهه نظر نٿو اچي ۽ لڳي ٿو تار خراب آهي.",
    "route.computer-android.3.h": "ڪمپيوٽر تي فون کوليو",
    "route.computer-android.3.p": "Windows تي فون File Explorer ۾ ان جي نالي سان نظر اچي ٿو. Mac تي Android سان مطابقت رکندڙ فائل ٽرانسفر ايپ استعمال ڪريو، يا ٻئي اوزار هڪ ئي Wi-Fi سان ڳنڍي LocalSend استعمال ڪريو.",
    "route.computer-android.4.h": "فائل ڪاپي ڪريو",
