    "route.iphone-android.2.h": "غوره: په دواړو LocalSend",
    "route.iphone-android.2.p": "په iPhone او Android تلیفون دواړو LocalSend نصب کړئ، دواړه په یو Wi-Fi کېږدئ — د VillageServer شبکه سمه ده — او واستوئ. نه انټرنټ، نه حساب.",
    "route.iphone-android.3.h": "که نوی اپ نشئ نصبولای",
    "route.iphone-android.3.p": "کمپیوټر هغه وخت د دواړو تلیفونونو ترمنځ فایل لېږدولی شي چې په دواړو کې فایل ته لاسرسی ولري. په iPhone کې File Sharing یو مناسب اپ ته اړتیا لري. د خپلو وسیلو لپاره د کمپیوټر او تلیفون ترمنځ لارښود تعقیب کړئ.",
    "route.iphone-android.4.h": "یا پخپله کارت وکاروئ",
    "route.iphone-android.4.p": "په هغه تلیفون کې چې د کارت ځای یا اډاپټر لري، فایل په microSD کارت کېږدئ او کارت یوسئ. له شبکې پرته دا تر ټولو باوري لار ده.",
    "route.iphone-android.5.h": "په یو کوچني فایل یې وازمویئ",
    "route.iphone-android.5.p": "هره لار چې غوره کړئ، لومړی یو PDF واستوئ او ډاډ ترلاسه کړئ چې پرانیستل کېږي.",
    "route.computer-iphone.name": "د کېبل له لارې، په Finder یا Apple Devices کې",
    "route.computer-iphone.1.h": "تلیفون ونښلوئ",
    "route.computer-iphone.1.p": "داسې سیم وکاروئ چې معلومات وړي. ډېر چارج سیمونه نه یې وړي او یو شان ښکاري — که کمپیوټر تلیفون هیڅ نه ښيي، تر هر څه مخکې بل سیم وازمویئ.",
    "route.computer-iphone.2.h": "په موبایل کې Trust کېکاږئ",
    "route.computer-iphone.2.p": "که iPhone کې “Trust this computer?” ښکاره شي، Trust کېکاږئ او د موبایل پاسکوډ ولیکئ. دا د موبایل او کمپیوټر ترمنځ د فایل لېږلو اجازه ورکوي.",
