    "route.computer-iphone.4.h": "فایل کاپي کړئ",
    "route.computer-iphone.4.p": "د Files یا په iTunes کې د File Sharing په برخه کې داسې اپ وټاکئ چې File Sharing ولري. تلیفون ته د لېږلو لپاره فایل په هغه اپ کې واچوئ. کمپیوټر ته د لېږلو لپاره فایل له هغه اپ څخه په کمپیوټر کې خوندي کړئ.",
    "route.computer-iphone.5.h": "ترلاسه شوی فایل وګورئ",
    "route.computer-iphone.5.p": "په iPhone کې فایل په هماغه اپ کې پرانیزئ چې د File Sharing لپاره مو کارولی و، یا یې په کمپیوټر کې په ټاکل شوي فولډر کې پرانیزئ. ډاډ ترلاسه کړئ چې فایل پرانیستل کېږي.",
    "route.computer-android.name": "په سیم، د فایل لېږد په حالت کې",
    "route.computer-android.1.h": "تلیفون ونښلوئ",
    "route.computer-android.1.p": "د معلوماتو سیم وکاروئ، نه یوازې د چارج.",
    "route.computer-android.2.h": "تلیفون د فایل لېږد ته واړوئ",
    "route.computer-android.2.p": "Android په خپله یوازې د چارج لپاره نښلي. هغه خبرتیا راښکته کړئ چې \"Charging this device via USB\" وایي، ویې ټکوئ او File Transfer وټاکئ. له دې پرته کمپیوټر هیڅ نه ویني او داسې ښکاري چې سیم خراب دی.",
    "route.computer-android.3.h": "په کمپیوټر کې تلیفون پرانیزئ",
    "route.computer-android.3.p": "په Windows کې تلیفون په File Explorer کې پرانیزئ. په Mac کې د Android لپاره مناسب فایل لېږدوونکی اپ وکاروئ، یا په دواړو وسیلو کې په یوه Wi-Fi شبکه کې LocalSend وکاروئ.",
    "route.computer-android.4.h": "فایل کاپي کړئ",
    "route.computer-android.4.p": "تلیفون ته د لېږلو لپاره فایل د هغه Download فولډر ته کاپي کړئ. کمپیوټر ته د لېږلو لپاره خوندي فایل له تلیفون څخه د کمپیوټر یوه فولډر ته کاپي کړئ.",
    "route.computer-android.5.h": "ترلاسه شوی فایل وګورئ",
    "route.computer-android.5.p": "فایل په ترلاسه کوونکې وسیله کې پرانیزئ. په Android کې Files، بیا Downloads یا خپل ټاکل شوی فولډر وګورئ. په کمپیوټر کې هغه فولډر وګورئ چې فایل مو ورته لېږلی و.",
    "route.card-iphone.name": "د Lightning یا USB-C پورټ کې کارت لوستونکی",
    "route.card-iphone.1.h": "تاسو لوستونکي ته اړتیا لرئ",
    "route.card-iphone.1.p": "iPhone د کارت ځای نه لري. داسې microSD لوستونکی پکار دی چې د تلیفون په خپل پورټ کې ولګېږي — په زړو iPhone کې Lightning، په نويو کې USB-C. له سفر مخکې وګورئ کوم یو دی.",
    "route.card-iphone.2.h": "کارت په لوستونکي کې، لوستونکی په تلیفون کې",
    "route.card-iphone.2.p": "د Files اپ په اړخیز لېست کې کارت د نوي ځای په توګه ښکاري.",
