    "share.golden.body": "Jaribu kwa PDF moja au faili moja ya sauti kabla ya kuhamisha kitu kikubwa. Faili ndogo ya majaribio inakuonyesha muunganisho mbovu kwa sekunde kumi badala ya dakika arobaini.",
    "share.teach": "Sasa waache wafanye wenyewe",
