    "nearby.lead": "Simu zote mbili zifungue ukurasa huu. Moja inatuma, nyingine inapokea. Faili inaenda moja kwa moja kutoka moja hadi nyingine.",
    "nearby.send.sub": "Nina faili",
    "nearby.receive.sub": "Nataka faili",
