  "nearby.offline": "Ouvrez cette page par Wi-Fi ou avec une connexion Internet. Si vous l’ouvrez directement depuis une carte, les deux téléphones ne peuvent pas se trouver. Utilisez alors le guide étape par étape.",
  "nearby.teach": "À son tour de partager : demandez à la personne de transmettre le fichier à quelqu’un d’autre maintenant, pendant que vous êtes là pour l’aider.",
