  "ui.catalog.missing.sub": "Si vous avez copié cette bibliothèque, copiez à nouveau le dossier entier sans changer les noms des dossiers.",
  "save.done.browser.title": "Téléchargement transmis à votre navigateur",
  "save.done.browser.where": "Vérifiez le dossier Téléchargements ou l’emplacement choisi. Ouvrez le fichier pour vérifier que l’enregistrement est terminé.",
  "bulk.done.browser.title": "Téléchargements transmis à votre navigateur pour {n} ressources",
