  "help.samsung.3.h": "ያስቀመጡትን ፋይል ይንኩ",
  "help.samsung.3.p": "መጽሐፉን፣ የድምፅ ቅጂውን ወይም ቪዲዮውን ይንኩ። ስልኩ ከጠየቀ የሚከፍተውን መተግበሪያ ይምረጡ። ፋይሉን ካላዩት፣ የፍለጋ ምልክቱን ይንኩና ስሙን ያስገቡ።",
