  "help.install.3.h": "በiPhone ወይም iPad ላይ",
  "help.install.3.p": "ቤተ መጻሕፍቱን በSafari ይክፈቱ። Share ይንኩ፣ ወይም የገጹን ምናሌ ከፍተው Share ይምረጡ። Add to Home Screen ከመረጡ በኋላ Add ይንኩ።",
  "help.install.4.h": "ይህ ምርጫ ካልታየ",
  "help.install.4.p": "ይህ ምርጫ እንደ መሣሪያዎና አሳሽዎ ይለያያል። ቤተ መጻሕፍቱን ከድረ ገጹ ወይም ከVillageServer Wi-Fi ይክፈቱ። በቀጥታ ከካርድ በተከፈተ ገጽ ላይ ላይታይ ይችላል።",
  "help.pi.h": "በVillageServer Wi-Fi በኩል",
