  "help.pi.1.p": "ከVillageServer Wi-Fi ጋር ይገናኙ። ይህ ኔትወርክ ኢንተርኔት የለውም፤ ይህ የተለመደ ነው፣ ቤተ መጻሕፍቱን ግን መጠቀም ይችላሉ።",
  "help.pi.2.h": "አድራሻውን በአሳሽ ይክፈቱ",
  "help.pi.2.p": "በመሣሪያው ላይ የተጻፈውን አድራሻ በአሳሽዎ ያስገቡ። ቤተ መጻሕፍቱ ይከፈታል።",
  "help.pi.3.h": "ለማቆየት የሚፈልጉትን ያስቀምጡ",
