  "share.item": "እነዚህ ደረጃዎች ይህን ይዘት ለማጋራት ናቸው። በካርዱ ውስጥ ላሉ ሌሎች ፋይሎችም ይሰራሉ።",
  "help.trouble.0.h": "ቤተ መጻሕፍቱ ይከፈታል፣ ግን ምንም አይታይም",
  "help.trouble.0.p": "የይዘት ዝርዝሩ ላይጫን ወይም ቅጂው ያልተሟላ ሊሆን ይችላል። ገጹን እንደገና ይጫኑ። ካርድ ቀድተው ከሆነ፣ ሙሉ ይዘቱን እንደገና ይቅዱ፣ የአቃፊዎችን ስሞችም አይቀይሩ።",
