  "help.trouble.2.h": "«ኢንተርኔት ያስፈልጋል» ይላል",
  "help.trouble.2.p": "በዚህ ካርድ ላይ የይዘቱ ዝርዝር ብቻ ተቀምጧል፤ ፋይሉ የለም። ለመክፈት መሣሪያውን ከኢንተርኔት ጋር ያገናኙ።",
  "help.trouble.3.h": "ያስቀመጥኩትን ፋይል ማግኘት አልቻልኩም",
  "help.trouble.3.p": "መጀመሪያ በDownloads ውስጥ ይፈልጉ። እዚያ ከሌለ፣ እንደገና ያስቀምጡና ስልኩ የሚያሳየውን የመቀመጫ ቦታ ያስተውሉ።",
  "route.iphone-iphone.name": "AirDrop",
  "route.iphone-iphone.1.h": "Wi-Fi እና Bluetooth ያብሩ",
  "route.iphone-iphone.1.p": "በሁለቱም iPhone ላይ Control Centre ከፍተው Wi-Fi እና Bluetooth ያብሩ። AirDrop ሁለቱንም ይጠቀማል፣ ከኔትወርክ ጋር መገናኘት ግን አያስፈልግም።",
