  "route.card-computer.1.p": "የኮምፒውተሩን የካርድ ማስገቢያ ወይም የUSB ካርድ አንባቢ ይጠቀሙ።",
  "route.card-computer.2.h": "ካርዱን ይክፈቱ",
  "route.card-computer.2.p": "እንደ ማከማቻ ይታያል። ቤተ መጻሕፍቱ app፣ media እና START-HERE ፋይሉን ጨምሮ ሙሉ አቃፊውን ይዟል።",
  "route.card-computer.3.h": "ሙሉ አቃፊውን ይቅዱ",
  "route.card-computer.3.p": "ቤተ መጻሕፍቱን ለመቅዳት ሁሉንም ፋይሎችና አቃፊዎች ይቅዱ። ስሞቻቸውን አይቀይሩ። ፋይሎቹ በመደበኛ ቦታቸው መቆየት አለባቸው።",
  "route.card-computer.4.h": "ካርዱን በትክክል ያውጡ",
  "route.card-computer.4.p": "መቅዳቱ እስኪጠናቀቅ ይጠብቁ። ካርዱን ከማውጣትዎ በፊት Eject ወይም Safely Remove ይምረጡ።",
  "route.computer-computer.name": "የUSB ማከማቻ ወይም LocalSend",
  "route.computer-computer.1.h": "በUSB ማከማቻ",
  "route.computer-computer.1.p": "ሙሉውን የቤተ መጻሕፍት አቃፊ ወደ USB ማከማቻ ይቅዱ። በሌላው ኮምፒውተር ያገናኙትና የአቃፊውን አደረጃጀት ሳይቀይሩ ይቅዱ።",
  "route.computer-computer.2.h": "በኔትወርክ በኩል",
  "route.computer-computer.2.p": "LocalSend በWindows፣ Mac እና Linux ላይ ይሰራል። በአንድ ኔትወርክ ላይ ባሉ መሣሪያዎች መካከል ያለ መለያና ያለ ኢንተርኔት ፋይሎችን ይልካል።",
  "route.computer-computer.3.h": "የአቃፊዎቹን መጠን ያወዳድሩ",
  "route.computer-computer.3.p": "በሁለቱም ኮምፒውተሮች ላይ የአቃፊው መጠን ተመሳሳይ መሆኑን ያረጋግጡ። የተቋረጠ ቅጂ የተጠናቀቀ ሊመስል ይችላል፣ አንዳንድ ፋይሎች ግን ሊጎድሉ ይችላሉ።",
  "route.computer-card.name": "ቤተ መጻሕፍቱን ወደ አዲስ ካርድ መቅዳት",
  "route.computer-card.1.h": "ሌላ ካርድ ለማዘጋጀት",
  "route.computer-card.1.p": "ለሌላ ሰው ለማጋራት ቤተ መጻሕፍቱን ወደ አዲስ microSD ካርድ ይቅዱ።",
  "route.computer-card.2.h": "መጀመሪያ አዲሱን ካርድ ያዘጋጁ",
  "route.computer-card.2.p": "ካርዱን ከሚያነቡት መሣሪያዎች ጋር የሚስማማ የፋይል ስርዓት ይምረጡ። exFAT ትልቅ ፋይሎችን ይቀበላል። በFAT32 አንድ ፋይል ከ4 GB ያነሰ መሆን አለበት። Format ማድረግ በካርዱ ላይ ያለውን ሁሉ ያጠፋል፤ ትክክለኛውን ካርድ መምረጥዎን ያረጋግጡ።",
  "route.computer-card.3.h": "ሁሉንም ይቅዱ",
  "route.computer-card.3.p": "START-HERE.html፣ app አቃፊ፣ media አቃፊ እና README.txt ይቅዱ። ሁሉንም ስሞች እንዳሉ ያቆዩ።",
  "route.computer-card.4.h": "ካርዱን ከመስጠትዎ በፊት ይፈትኑ",
  "route.computer-card.4.p": "ካርዱን በስልክ ያስገቡና START-HERE.html ይክፈቱ። ፊልም ያጫውቱ፣ PDF ይክፈቱና መሥራታቸውን ያረጋግጡ።",
