  "home.help": "How I go open wetin I save?",
  "home.help.sub": "Where files dey go and how to find dem again",
  "home.pick": "Choose your language",
  "home.pick.sub": "You fit change am anytime",
  "lib.title": "See wetin dey di library",
  "lib.search": "Search with name",
